import pathlib,importlib.util,json,datetime,subprocess
R=pathlib.Path(__file__).resolve().parent;sp=importlib.util.spec_from_file_location('c6db',R/'isolated_db.py');m=importlib.util.module_from_spec(sp);sp.loader.exec_module(m)
def mysql(q):
 s,_=m.owned('mysql');return m.run(['exec','-i','-e','MYSQL_PWD='+s['root_password'],s['id'],'mysql','--batch','--raw','--skip-column-names','-uroot'],q)
r={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'initial_orbstack_before_first_docker_inventory':'Stopped (orb list empty); first authorized docker inventory auto-started daemon; subsequent initial-inventory.json Running. No external containers or Linux VMs observed.','c5_evidence':'Read-only helper/cache reference; C5 files not overwritten.','images_downloaded_or_installed':False,'storage_medium':'Bounded tmpfs RAM-backed within OrbStack VM; transaction/process-crash evidence only, no power-loss durability acceptance.','capacity_status':'NOT_RUN; only environment initialization/metadata capture. Mysql diagnostic case allocated exclusive to core by root.','configuration_difference_from_c5':'MySQL P_S ON with bounded digest/history and statement consumers, C5 P_S OFF. PG pg_stat_statements and track_io_timing ON, C5 default off. Formal capacity comparison requires identical settings on both runs.','engines':{}}
for engine in ['pg','mysql']:
 s,i=m.owned(engine);e={'id':s['id'],'owner':s['owner'],'image_reference':s['image'],'image_id':i['Image'],'role':s['user'],'bootstrap_database':s['database'],'endpoint':s['endpoint'],'cases':s['cases'],'limits':{'memory_bytes':i['HostConfig']['Memory'],'memory_swap_bytes':i['HostConfig']['MemorySwap'],'nano_cpus':i['HostConfig']['NanoCpus'],'pids':i['HostConfig']['PidsLimit'],'tmpfs':i['HostConfig']['Tmpfs'],'shm_bytes':i['HostConfig']['ShmSize'],'readonly_rootfs':i['HostConfig']['ReadonlyRootfs']},'mounts':i['Mounts'],'ports':i['NetworkSettings']['Ports'],'datadir_filesystem':m.run(['exec',s['id'],'df','-T','/var/lib/postgresql/data' if engine=='pg' else '/var/lib/mysql'])}
 if engine=='pg':
  e['configuration']=json.loads(m.sql('pg',"SELECT json_build_object('version',version(),'isolation',current_setting('default_transaction_isolation'),'fsync',current_setting('fsync'),'full_page_writes',current_setting('full_page_writes'),'synchronous_commit',current_setting('synchronous_commit'),'shared_preload_libraries',current_setting('shared_preload_libraries'),'track_io_timing',current_setting('track_io_timing'),'pg_stat_statements_max',current_setting('pg_stat_statements.max'),'pg_stat_statements_track',current_setting('pg_stat_statements.track'),'max_connections',current_setting('max_connections'),'collation',(SELECT datcollate FROM pg_database WHERE datname=current_database()));"))
  e['app_role_capabilities']=m.sql('pg',"SELECT rolname,rolsuper,rolcreatedb,rolcreaterole,rolcanlogin FROM pg_roles WHERE rolname='"+s['user']+"';")
  e['app_role_memberships']=m.sql('pg',"SELECT parent.rolname FROM pg_auth_members am JOIN pg_roles member ON am.member=member.oid JOIN pg_roles parent ON am.roleid=parent.oid WHERE member.rolname='"+s['user']+"';")
  e['pg_stat_statements_extension']=m.sql('pg',"SELECT extversion FROM pg_extension WHERE extname='pg_stat_statements';")
 else:
  e['configuration']=json.loads(mysql("SELECT JSON_OBJECT('version',VERSION(),'engine',@@default_storage_engine,'isolation',@@transaction_isolation,'flush_log_at_trx_commit',@@innodb_flush_log_at_trx_commit,'sync_binlog',@@sync_binlog,'log_bin',@@log_bin,'rollback_on_timeout',@@innodb_rollback_on_timeout,'collation',@@collation_server,'lower_case_table_names',@@lower_case_table_names,'partial_revokes',@@partial_revokes,'triggertrust',@@log_bin_trust_function_creators,'performance_schema',@@performance_schema,'digest_size',@@performance_schema_digests_size,'history_size',@@performance_schema_events_statements_history_size,'history_long_size',@@performance_schema_events_statements_history_long_size,'max_sql_text',@@performance_schema_max_sql_text_length,'max_digest_length',@@performance_schema_max_digest_length,'buffer_pool_bytes',@@innodb_buffer_pool_size,'redo_log_bytes',@@innodb_redo_log_capacity);"))
  e['app_role_grants']=mysql('SHOW GRANTS FOR '+repr(s['user'])+"@'%';").splitlines()
  e['consumers']=mysql("SELECT NAME,ENABLED FROM performance_schema.setup_consumers WHERE NAME LIKE '%statement%' OR NAME IN('global_instrumentation','thread_instrumentation');").splitlines()
  e['statement_instrument_summary']=mysql("SELECT ENABLED,TIMED,COUNT(*) FROM performance_schema.setup_instruments WHERE NAME LIKE 'statement/%' GROUP BY ENABLED,TIMED;").splitlines()
  e['ps_memory_current_bytes']=mysql('SELECT SUM(CURRENT_NUMBER_OF_BYTES_USED) FROM performance_schema.memory_summary_global_by_event_name;')
  e['performance_schema_instrumented_own_memory_bytes']=mysql("SELECT SUM(CURRENT_NUMBER_OF_BYTES_USED) FROM performance_schema.memory_summary_global_by_event_name WHERE EVENT_NAME LIKE 'memory/performance_schema/%';")
  e['ps_memory_counter_scope']='ps_memory_current_bytes covers all server instruments; performance_schema_instrumented_own_memory_bytes filters P_S allocations, not a paired runtime overhead measurement.'
  e['ps_lost_counters']=mysql("SHOW GLOBAL STATUS LIKE 'Performance_schema%lost';").splitlines()
 r['engines'][engine]=e
for key,args in [('host_processes',['ps','-axo','pid=,ppid=,%cpu=,%mem=,comm=']),('host_memory',['vm_stat']),('host_load',['uptime']),('container_stats',['docker','--context','orbstack','stats','--no-stream','--format','{{json .}}'])]:
 p=subprocess.run(args,capture_output=True,text=True);r[key]={'exit_code':p.returncode,'stdout':p.stdout,'stderr':p.stderr}
m.save(R/'environment-receipt.json',r)
print(json.dumps({'configuration':{k:v['configuration'] for k,v in r['engines'].items()},'app_role_capabilities':r['engines']['pg']['app_role_capabilities'],'mysql_ps_memory_current_bytes':r['engines']['mysql']['ps_memory_current_bytes'],'container_stats':r['container_stats']},indent=2))
